#!/usr/bin/env node
// opc.mjs —— OPC 底座唯一的命令行入口（分发器）。
// 用法：node scripts/opc.mjs <子命令> [--dir 项目根] [--json '<数据>'] [--id x] [--gen n]
// 成功时 stdout 输出一行 JSON 结果；出错时 stderr 打白话原因、按 EXIT 表退出。
// 唯一例外：format-doc 打整份骨架、team index 先打人读的增删改摘要（契约就要它进 stdout），
// 末行才是 JSON 结果——调用方解析 stdout 一律只取末行，别对整段 JSON.parse。
//
// 分发器职责链（后续任务往对应位置挂钩，不改前后顺序）：
//   解析参数 → 找到项目的 .opc/ → 版本预检（档案版本不符先跑迁移链）
//   → 代数围栏与自动续租 → 路由到 lib 里的实现。
// 铁律：本文件只做分发、参数解析和出错转白话，不写业务判定；
// 对 .opc/ 的一切文件写入都经 lib/store.mjs，绝不直接碰文件系统。

import os from 'node:os';
import path from 'node:path';
import { existsSync, realpathSync } from 'node:fs';
import {
  EXIT,
  WRITE_TYPES,
  PATHS,
  TASTE_EXAMPLE_KINDS,
  RUNTIME_CURRENT_SESSION_PATH,
  DISPATCH_SPECIAL_EMPLOYEES,
  resolveDispatchAllowedModels,
  assertMemberModelsExistInTeam,
  isTeamRosterMember
} from './lib/schemas.mjs';
import { opcDir, readJson, writeJson, writeText, writeBytes, appendLine, scaffoldProject } from './lib/store.mjs';
import { checkNarrative } from './lib/narrative.mjs';
import { advance, activateMilestone, IllegalTransition } from './lib/statemachine.mjs';
import { acquire, renew, release, readLock, isHolderProcessAlive } from './lib/lock.mjs';
import { migrateIfNeeded } from './lib/migrate.mjs';
import { ingest, backfill, clearLedgerGap } from './lib/ledger.mjs';
import { runAcceptance } from './lib/acceptance.mjs';
import { decide, resumeProject, markExecuted } from './lib/approvals.mjs';
import { precheck, loadTeamDoc, pickMainMilestone } from './lib/precheck.mjs';
import { render, tickEnd } from './lib/report.mjs';
import { statusSnapshot, auditTimeline } from './lib/audit.mjs';
import { assembleDashboard } from './lib/dashboard.mjs';
import { fire } from './lib/fire.mjs';
import { renderFormatDoc } from './lib/formatdoc.mjs';
import { buildIndex, scaffoldTeam, renderTeam, validateTeamBundle } from './lib/team.mjs';
import { issueExamRecord } from './lib/exam.mjs';
import { verifySiteRun } from './lib/service-check.mjs';
import {
  addArtifact,
  upsertArtifactBySource,
  listArtifacts,
  removeArtifact,
  registerArtifactFromTasteExample,
  readArtifactFileBytes,
  listArtifactDir,
  runHasPortPlaceholder
} from './lib/artifact.mjs';

// 里程碑清单的存放位置以写入类型表声明的为准，不另抄一份路径字面量（tick-begin 落指针、
// artifact add fallback 盖戳都要读它）。
const MILESTONES_REL = WRITE_TYPES['phase1-milestones'].path();

// 带退出码的错误：业务代码抛它，CLI 收尾时按 exitCode 退出；不带退出码的错误一律按 EXIT.ERROR。
class CliError extends Error {
  constructor(message, exitCode = EXIT.ERROR) {
    super(message);
    this.exitCode = exitCode;
  }
}

// 解析命令行：第一个不带 -- 的词是子命令，其余不带 -- 的词按顺序进 positionals；
// 「--名 值」进 flags；--名 后面直接跟另一个 --名（或到头了）就当开关记 true。
function parseArgs(argv) {
  const positionals = [];
  const flags = {};
  for (let i = 0; i < argv.length; i++) {
    const token = argv[i];
    if (token.startsWith('--')) {
      const name = token.slice(2);
      const next = argv[i + 1];
      if (next === undefined || next.startsWith('--')) {
        flags[name] = true;
      } else {
