1	// 念念 · 陈列室 —— 图片二进制存取模块（U1-S2·存储换血）
2	//
3	// 职责：把照片二进制（Blob）存进 IndexedDB，键为图片引用 id（imageRef）。状态树（LocalStorage）
4	//  只保留这个引用 id ＋ 宽高比等元信息，二进制 / base64 一律不进 LocalStorage —— 由
5	//  storage/persistence 的 saveState 在序列化前把内联图片（data:/blob:）搬到这里、只留引用。
6	//
7	// 契约：
8	//  - 纯前端、无后端；IndexedDB 不可用（SSR / 老浏览器 / 部分隐私模式）时优雅降级：
9	//    isImageStoreAvailable() 返回 false；写（putImage）以 reject 冒泡让上层感知，读（getImage/hasImage）
10	//    返回空、不抛，避免读侧连累渲染。
11	//  - 所有写 / 读失败一律以 reject 冒泡，绝不静默吞 —— 配合 U1-S2「终结静默失败」。
12	
13	const DB_NAME = 'memories.images';
14	const DB_VERSION = 1;
15	const STORE = 'images';
16	
17	/** IndexedDB 是否可用（SSR / 无 indexedDB 环境下为 false）。 */
18	export function isImageStoreAvailable(): boolean {
19	  return typeof indexedDB !== 'undefined';
20	}
21	
22	// 单例连接（同一会话内复用）；打开失败即清空缓存、允许下次重试。
23	let dbPromise: Promise<IDBDatabase> | null = null;
24	
25	function openDb(): Promise<IDBDatabase> {
26	  if (!isImageStoreAvailable()) {
27	    return Promise.reject(new Error('IndexedDB 不可用'));
28	  }
29	  if (dbPromise) return dbPromise;
30	  dbPromise = new Promise<IDBDatabase>((resolve, reject) => {
31	    const req = indexedDB.open(DB_NAME, DB_VERSION);
32	    req.onupgradeneeded = () => {
33	      const db = req.result;
34	      if (!db.objectStoreNames.contains(STORE)) {
35	        // 显式 key（外部传入 imageRef），不用 keyPath / autoIncrement。
36	        db.createObjectStore(STORE);
37	      }
38	    };
39	    req.onsuccess = () => resolve(req.result);
40	    req.onerror = () => reject(req.error ?? new Error('打开 IndexedDB 失败'));
41	  });
42	  dbPromise.catch(() => {
43	    dbPromise = null;
44	  });
45	  return dbPromise;
46	}
47	
48	/** 把一次对象仓事务包成 Promise（成功 resolve 请求结果，失败 / 中止 reject）。 */
49	function runTx<T>(
50	  mode: IDBTransactionMode,
51	  fn: (store: IDBObjectStore) => IDBRequest<T>,
52	): Promise<T> {
53	  return openDb().then(
54	    (db) =>
55	      new Promise<T>((resolve, reject) => {
56	        const tx = db.transaction(STORE, mode);
57	        const store = tx.objectStore(STORE);
58	        const req = fn(store);
59	        req.onsuccess = () => resolve(req.result);
60	        req.onerror = () => reject(req.error ?? new Error('IndexedDB 操作失败'));
61	        tx.onabort = () => reject(tx.error ?? new Error('IndexedDB 事务中止'));
62	      }),
63	  );
64	}
65	
66	/** 存入 / 覆盖一张图片二进制。写入失败（磁盘满 / 隐私模式等）以 reject 冒泡。 */
67	export function putImage(id: string, blob: Blob): Promise<void> {
68	  return runTx('readwrite', (store) => store.put(blob, id)).then(() => undefined);
69	}
70	
71	/** 读回一张图片二进制；无则 undefined。IndexedDB 不可用时返回 undefined（不抛，读侧不连累渲染）。 */
72	export function getImage(id: string): Promise<Blob | undefined> {
73	  if (!isImageStoreAvailable()) return Promise.resolve(undefined);
74	  return runTx<Blob | undefined>(
75	    'readonly',
76	    (store) => store.get(id) as IDBRequest<Blob | undefined>,
77	  );
78	}
79	
80	/** 是否已存该图片（供 saveState 幂等去重，避免每次全量落盘都重复写同一张二进制）。 */
81	export function hasImage(id: string): Promise<boolean> {
82	  if (!isImageStoreAvailable()) return Promise.resolve(false);
83	  return runTx<number>('readonly', (store) => store.count(id)).then((n) => n > 0);
84	}
85	
86	/** 删除一张图片二进制。 */
87	export function deleteImage(id: string): Promise<void> {
88	  if (!isImageStoreAvailable()) return Promise.resolve();
89	  return runTx('readwrite', (store) => store.delete(id)).then(() => undefined);
90	}
91	
92	/**
93	 * 读回图片并生成一个会话内 object URL（供渲染层 hydrate 用户上传件；无则 undefined）。
94	 * 调用方在不再需要时负责 URL.revokeObjectURL 释放。渲染链接入属 U2/U3，本期先备好口子。
95	 */
96	export function getImageObjectURL(id: string): Promise<string | undefined> {
97	  return getImage(id).then((blob) => (blob ? URL.createObjectURL(blob) : undefined));
98	}
99	
100	/**
101	 * 把 data: URL（base64 或百分号编码）解成 Blob —— 供把内联图片搬进 IndexedDB。
102	 * 非 data: URL 抛错（交由上层决定是否继续）。
103	 */
104	export function dataURLToBlob(dataURL: string): Blob {
105	  const comma = dataURL.indexOf(',');
106	  if (!dataURL.startsWith('data:') || comma < 0) {
107	    throw new Error('不是合法的 data: URL');
108	  }
109	  const header = dataURL.slice(5, comma); // 形如 "image/png;base64"
110	  const isBase64 = /;base64/i.test(header);
111	  const mime = header.split(';')[0] || 'application/octet-stream';
112	  const data = dataURL.slice(comma + 1);
113	  if (isBase64) {
114	    const bin = atob(data);
115	    const bytes = new Uint8Array(bin.length);
116	    for (let i = 0; i < bin.length; i += 1) bytes[i] = bin.charCodeAt(i);
117	    return new Blob([bytes], { type: mime });
118	  }
119	  return new Blob([decodeURIComponent(data)], { type: mime });
120	}
121

