70	// —— reducer ——
71	
72	export function galleryReducer(state: GalleryState, action: GalleryAction): GalleryState {
73	  switch (action.type) {
74	    case 'create-scene': {
75	      // 守卫：达上限、背景已被占用、或背景不存在 → 拒绝（背景不可重复、上限 3）。
76	      if (state.scenes.length >= MAX_SCENES) return state;
77	      const bg = BACKGROUNDS.find((b) => b.id === action.backgroundId);
78	      if (!bg) return state;
79	      if (state.scenes.some((s) => s.backgroundId === bg.id)) return state;
80	
81	      const scene: Scene = { id: newId('scene'), name: bg.name, backgroundId: bg.id };
82	      return { ...state, scenes: [...state.scenes, scene], activeSceneId: scene.id };
83	    }
84	
85	    case 'select-scene': {
86	      if (!state.scenes.some((s) => s.id === action.sceneId)) return state;
87	      if (state.activeSceneId === action.sceneId) return state;
88	      return { ...state, activeSceneId: action.sceneId };
89	    }
90	
91	    case 'rename-scene': {
92	      // 场景就地重命名（chip 点进去改）：只改 name，其余字段不动。空白名忽略（保底不产生空 chip）。
93	      const name = action.name.trim();
94	      if (!name) return state;
95	      const target = state.scenes.find((s) => s.id === action.sceneId);
96	      if (!target) return state;
97	      if (target.name === name) return state; // 无变化 → 免去一次全量落盘
98	      return {
99	        ...state,
100	        scenes: state.scenes.map((s) => (s.id === action.sceneId ? { ...s, name } : s)),
101	      };
102	    }
103	
104	    case 'delete-scene': {
105	      // 场景删除（chip 次级入口）：移除该场景 + 其名下所有摆放。因 availableBackgrounds/canAddScene
106	      //  都由 scenes 派生，删除后该背景即刻回到可选池（配额释放、可再建）。删的是当前激活场景时，
107	      //  把激活位交给剩余场景的第一个（无剩余则 null）。
108	      const target = state.scenes.find((s) => s.id === action.sceneId);
109	      if (!target) return state;
110	      const scenes = state.scenes.filter((s) => s.id !== action.sceneId);
111	      const placements = state.placements.filter((p) => p.sceneId !== action.sceneId);
112	      const activeSceneId =
113	        state.activeSceneId === action.sceneId
114	          ? scenes.length > 0
115	            ? scenes[0].id
116	            : null
117	          : state.activeSceneId;
118	      return { ...state, scenes, placements, activeSceneId };
119	    }
120	
121	    case 'set-mode': {
122	      if (state.mode === action.mode) return state;
123	      return { ...state, mode: action.mode };
124	    }
125	
126	    case 'place-item': {
127	      // 只在编辑模式、且有激活场景时把物件放入当前画布。
128	      if (state.mode !== 'edit') return state;
129	      const sceneId = state.activeSceneId;
130	      if (!sceneId) return state;
131	      if (!state.items.some((i) => i.id === action.itemId)) return state;
132	
133	      const n = state.placements.filter((p) => p.sceneId === sceneId).length;
134	      const rotations = [-5, 4, -3, 6, -6, 3];
135	      // N2（schema v3）：x/y 存物件**中心**在场景图坐标系内的百分比、w 存宽度占图宽的百分比。
136	      //  - 抽屉拖入：带落点坐标（x/y，已由上层换算成图内中心百分比）→ 落在指针放手处（允许出界进补边区）；
137	      //  - 点选放入：不带 → 走默认网格位（以中心百分比铺开，四列一行、留出四周呼吸区）。
138	      const dropped = typeof action.x === 'number' && typeof action.y === 'number';
139	      const placement: Placement = {
140	        id: newId('pl'),
141	        sceneId,
142	        itemId: action.itemId,
143	        x: dropped ? action.x! : 18 + (n % 4) * 21,
144	        y: dropped ? action.y! : 24 + Math.floor(n / 4) * 20,
145	        w: DEFAULT_ITEM_W,
146	        rotation: rotations[n % rotations.length],
147	        z: n + 1,
148	      };
