155	      if (!state.placements.some((p) => p.id === action.placementId)) return state;
156	      return {
157	        ...state,
158	        placements: state.placements.map((p) =>
159	          p.id === action.placementId ? { ...p, x: action.x, y: action.y } : p,
160	        ),
161	      };
162	    }
163	
164	    case 'resize-placement': {
165	      // 角手柄缩放松手后的提交：只改 w（宽占图宽百分比），x/y/rotation/z 原样保留。
166	      if (state.mode !== 'edit') return state;
167	      if (!state.placements.some((p) => p.id === action.placementId)) return state;
168	      return {
169	        ...state,
170	        placements: state.placements.map((p) =>
171	          p.id === action.placementId ? { ...p, w: action.w } : p,
172	        ),
173	      };
174	    }
175	
176	    case 'rotate-placement': {
177	      // 顶部手柄旋转松手后的提交：只改 rotation，x/y/scale/z 原样保留。
178	      if (state.mode !== 'edit') return state;
179	      if (!state.placements.some((p) => p.id === action.placementId)) return state;
180	      return {
181	        ...state,
182	        placements: state.placements.map((p) =>
183	          p.id === action.placementId ? { ...p, rotation: action.rotation } : p,
184	        ),
185	      };
186	    }
187	
188	    case 'remove-placement': {
189	      if (state.mode !== 'edit') return state;
190	      return {
191	        ...state,
192	        placements: state.placements.filter((p) => p.id !== action.placementId),
193	      };
194	    }
195	
196	    case 'set-item-story': {
197	      // 故事挂在 Item 本身（不挂 Placement）：只改目标 Item 的 story 字段，其余字段与所有
198	      // Placement 原样不动。因是改 Item，同一 Item 在任何场景的 Placement 都读回同一段故事 →
