203	      if (target.story === action.story) return state; // 无变化 → 免去一次全量落盘
204	      return {
205	        ...state,
206	        items: state.items.map((i) =>
207	          i.id === action.itemId ? { ...i, story: action.story } : i,
208	        ),
209	      };
210	    }
211	
212	    case 'set-item-name': {
213	      // 物件重命名：名字挂在 Item 本身（不挂 Placement）→ 同一 Item 在任何场景的所有 Placement
214	      //  都读回同一个名字，天然跨场景同步。空白名忽略（保底不产生无名物件）。仅编辑模式可写。
215	      if (state.mode !== 'edit') return state;
216	      const name = action.name.trim();
217	      if (!name) return state;
218	      const target = state.items.find((i) => i.id === action.itemId);
219	      if (!target) return state;
220	      if (target.name === name) return state; // 无变化 → 免去一次全量落盘
221	      return {
222	        ...state,
223	        items: state.items.map((i) => (i.id === action.itemId ? { ...i, name } : i)),
224	      };
225	    }
226	
227	    case 'set-gallery-name': {
228	      // 陈列室名（品牌章）就地编辑：改 galleryName，随状态持久化。空白名忽略。
229	      const name = action.name.trim();
230	      if (!name) return state;
231	      if (state.galleryName === name) return state;
232	      return { ...state, galleryName: name };
233	    }
234	
235	    default:
236	      return state;
237	  }
238	}
