60:// 状态流转总入口。kind 是对象种类（project/milestone/sprint/tick），
61-// id 指明哪一个（project 全项目只有一个，不用 id），toState 是目标状态。
62-// 返回 {kind, id, from, to, incident}，incident 表示这次流转有没有触发三振熔断。
63-export async function advance(root, kind, id, toState, { actor } = {}) {
64-  if (typeof actor !== 'string' || actor.trim() === '') {
65-    throw new Error('advance 必须注明 actor（这次是谁在推状态）');
66-  }
67-  switch (kind) {
68-    case 'project':
69-      return advanceProject(root, toState, actor);
70-    case 'milestone':
71-      return advanceMilestone(root, id, toState, actor);
72:    case 'sprint':
73-      return advanceSprint(root, id, toState, actor);
74-    case 'tick':
75-      return advanceTick(root, id, toState, actor);
76-    default:
77:      throw new Error(`不认识的对象种类「${kind}」，只认识 project、milestone、sprint、tick`);
78-  }
79-}
